<section class="panel"><h2>Accountability trail</h2><p>Most recent 250 events. All inventory mutations and their logs commit together.</p><table><tr><th>Time</th><th>User</th><th>Action</th><th>Details</th></tr><?php foreach(query('SELECT l.*,u.name FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.id DESC LIMIT 250')->fetchAll() as $r): ?><tr><td><?= e($r['created_at']) ?></td><td><?= e($r['name']??'System') ?></td><td><?= e($r['action']) ?></td><td><?= e($r['details']) ?></td></tr><?php endforeach ?></table></section>
